import { useEffect, useState } from 'react'
import { navigate } from '../engine/router.ts'
import { BackButton } from '../components/ui.tsx'

// Generated by `npm run tts:samples`: the same hard sentences in every vi-VN voice.
type Samples = { generatedAt: string; samples: string[]; voices: { name: string; files: string[] }[] }

export function Voices() {
  const [data, setData] = useState<Samples | null | 'missing'>(null)

  useEffect(() => {
    fetch('/audio/samples/manifest.json')
      .then((r) => (r.ok ? r.json() : 'missing'))
      .then(setData)
      .catch(() => setData('missing'))
  }, [])

  const play = (file: string) => new Audio(`/audio/samples/${file}`).play()

  return (
    <div className="h-full overflow-auto">
      <div className="flex flex-col gap-6 p-6">
        <header className="flex items-center gap-4">
          <BackButton onClick={() => navigate({ name: 'parent' })} />
          <h1 className="text-3xl font-extrabold">Nghe thử giọng đọc</h1>
        </header>
        {data === null && <p>Đang tải…</p>}
        {data === 'missing' && (
          <p className="text-lg">
            Chưa có file mẫu. Chạy <code className="rounded bg-line px-2">npm run tts:samples</code> (cần <code>GOOGLE_TTS_API_KEY</code> trong{' '}
            <code>.env.local</code>).
          </p>
        )}
        {data && data !== 'missing' && (
          <>
            <p className="text-muted">
              Chọn giọng nghe rõ dấu thanh nhất, rồi đặt <code className="rounded bg-line px-2">TTS_VOICE=&lt;tên giọng&gt;</code> trong <code>.env.local</code>.
            </p>
            <table className="border-collapse text-left">
              <thead>
                <tr>
                  <th className="sticky left-0 bg-paper p-2">Câu mẫu</th>
                  {data.voices.map((v) => (
                    <th key={v.name} className="whitespace-nowrap p-2 font-mono text-sm">
                      {v.name}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {data.samples.map((text, i) => (
                  <tr key={text} className="border-t-2 border-line">
                    <td className="sticky left-0 bg-paper p-2 font-school text-xl">{text}</td>
                    {data.voices.map((v) => (
                      <td key={v.name} className="p-2 text-center">
                        <button className="rounded-xl border-2 border-line bg-card px-3 py-1 text-2xl" onClick={() => play(v.files[i])}>
                          ▶️
                        </button>
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </>
        )}
      </div>
    </div>
  )
}
